if isinstance(value, list):
    # Extract columns directly from the list-of-lists instead of
    # converting to an object array and back (list → array → .tolist()).
    n_cols = len(value[0])

    def get_col(i: int):
        return [row[i] for row in value]

else:
    if not is_array_like(value):
        value = np.asarray(value)
    n_cols = value.shape[1]
    is_object = is_object_dtype(value.dtype)

    def get_col(i: int):
        value_col = value[:, i]
        if is_object:
            value_col = value_col.tolist()
        return value_col

if len(ilocs) != n_cols:
    raise ValueError(
        "Must have equal len keys and value when setting with an ndarray"
    )
for i, loc in enumerate(ilocs):
    self._setitem_single_column(loc, get_col(i), pi)
